// See README.md for license details.
// -----------------------------------------------------------------------------
//  multiWidthRegister.scala — Multi-width aliased register file
//
//  Parameters:
//    L    — number of base VX registers (must be divisible by 4); default 32
//    K    — SIMD lane count per register; default 8
//    N    — base lane width in bits (N(bits)); default 8
//
//  Physical storage: L × K bytes (one N-bit byte per lane per VX entry).
//
//  Register-class views (byte-level aliasing):
//    VX[0..L-1]     — L  registers of K × N    bits  (one VX entry per storage row)
//    VE[0..L/2-1]   — 16 registers of K × 2N   bits  (VE[i] = VX[2i] ∥ VX[2i+1])
//    VR[0..L/4-1]   — 8  registers of K × 4N   bits  (VR[i] = VX[4i..4i+3])
//
//  Writing VR[i] atomically updates the four underlying VX rows.
//  Conflict resolution: last writer wins per row (software responsibility).
//
//  Addressing:
//    VX addr: 5 bits (log2Ceil(L))
//    VE addr: 4 bits (log2Ceil(L/2))
//    VR addr: 3 bits (log2Ceil(L/4))
//
//  Port layout:
//    VX: vx_rd read ports, vx_wr write ports (for INT8 VALU results)
//    VE: ve_rd read ports, ve_wr write ports (for INT16 VALU results)
//    VR: vr_rd read ports, vr_wr write ports (for INT32/FP32; includes MMALU direct)
//    ext_rd / ext_wr: external test-harness ports (VX width)
// -----------------------------------------------------------------------------

package sram.mwreg

import chisel3._
import chisel3.util._

class MultiWidthRegisterBlock(
    val L:      Int = 32,   // number of VX registers; must be divisible by 4
    val K:      Int = 8,    // SIMD lane count per register
    val N:      Int = 8,    // base lane width in bits; VX=N, VE=2N, VR=4N
    val vx_rd:  Int = 4,    // VX read ports
    val vx_wr:  Int = 2,    // VX write ports
    val ve_rd:  Int = 2,    // VE read ports
    val ve_wr:  Int = 1,    // VE write ports
    val vr_rd:  Int = 2,    // VR read ports
    val vr_wr:  Int = 2,    // VR write ports (port 0=VALU, port 1=MMALU direct)
) extends Module {

  require(L % 4 == 0, s"MultiWidthRegisterBlock: L=$L must be divisible by 4")
  require(N > 0 && K > 0 && L > 0)

  val VE_SIZE = L / 2
  val VR_SIZE = L / 4

  val VX_ADDR = log2Ceil(L)
  val VE_ADDR = log2Ceil(VE_SIZE)
  val VR_ADDR = log2Ceil(VR_SIZE)

  val io = IO(new Bundle {
    // ---- VX ports (K lanes of N bits each) ----
    val vx_r_addr = Input(Vec(vx_rd, UInt(VX_ADDR.W)))
    val vx_r_data = Output(Vec(vx_rd, Vec(K, UInt(N.W))))
    val vx_w_addr = Input(Vec(vx_wr, UInt(VX_ADDR.W)))
    val vx_w_data = Input(Vec(vx_wr, Vec(K, UInt(N.W))))
    val vx_w_en   = Input(Vec(vx_wr, Bool()))

    // ---- VE ports (K lanes of 2N bits each) ----
    val ve_r_addr = Input(Vec(ve_rd, UInt(VE_ADDR.W)))
    val ve_r_data = Output(Vec(ve_rd, Vec(K, UInt((2*N).W))))
    val ve_w_addr = Input(Vec(ve_wr, UInt(VE_ADDR.W)))
    val ve_w_data = Input(Vec(ve_wr, Vec(K, UInt((2*N).W))))
    val ve_w_en   = Input(Vec(ve_wr, Bool()))

    // ---- VR ports (K lanes of 4N bits each) ----
    val vr_r_addr = Input(Vec(vr_rd, UInt(VR_ADDR.W)))
    val vr_r_data = Output(Vec(vr_rd, Vec(K, UInt((4*N).W))))
    val vr_w_addr = Input(Vec(vr_wr, UInt(VR_ADDR.W)))
    val vr_w_data = Input(Vec(vr_wr, Vec(K, UInt((4*N).W))))
    val vr_w_en   = Input(Vec(vr_wr, Bool()))

    // ---- External test-harness ports (VX width) ----
    val ext_r_addr = Input(UInt(VX_ADDR.W))
    val ext_r_data = Output(Vec(K, UInt(N.W)))
    val ext_w_addr = Input(UInt(VX_ADDR.W))
    val ext_w_data = Input(Vec(K, UInt(N.W)))
    val ext_w_en   = Input(Bool())
  })

  // ---------- Physical storage: L rows of K lanes of N bits ----------
  // Each row corresponds to one VX register.
  val mem = RegInit(VecInit(Seq.fill(L)(VecInit(Seq.fill(K)(0.U(N.W))))))

  // ---------- Async read: VX ----------
  for (p <- 0 until vx_rd) {
    for (lane <- 0 until K) {
      io.vx_r_data(p)(lane) := mem(io.vx_r_addr(p))(lane)
    }
  }

  // ---------- Async read: VE (pack 2 consecutive VX rows) ----------
  // VE[i] row j: mem[2i][lane] in low N bits, mem[2i+1][lane] in high N bits
  for (p <- 0 until ve_rd) {
    val baseRow = io.ve_r_addr(p) ## 0.U(1.W)  // *2
    for (lane <- 0 until K) {
      val lo = mem(baseRow)(lane)
      val hi = mem(baseRow + 1.U)(lane)
      io.ve_r_data(p)(lane) := Cat(hi, lo)
    }
  }

  // ---------- Async read: VR (pack 4 consecutive VX rows) ----------
  for (p <- 0 until vr_rd) {
    val baseRow = io.vr_r_addr(p) ## 0.U(2.W)  // *4
    for (lane <- 0 until K) {
      val b0 = mem(baseRow + 0.U)(lane)
      val b1 = mem(baseRow + 1.U)(lane)
      val b2 = mem(baseRow + 2.U)(lane)
      val b3 = mem(baseRow + 3.U)(lane)
      io.vr_r_data(p)(lane) := Cat(b3, b2, b1, b0)
    }
  }

  // ---------- External read ----------
  for (lane <- 0 until K) {
    io.ext_r_data(lane) := mem(io.ext_r_addr)(lane)
  }

  // ---------- Write: default all rows disabled each cycle ----------
  // We compute a merged write per row using a priority scheme:
  // VR > VE > VX > ext (highest priority wins for each row)
  // This avoids inferring multi-driven registers.

  val wr_data = Wire(Vec(L, Vec(K, UInt(N.W))))
  val wr_en   = Wire(Vec(L, Bool()))

  // Start with all disabled
  for (row <- 0 until L) {
    wr_en(row)  := false.B
    for (lane <- 0 until K) wr_data(row)(lane) := 0.U
  }

  // External write (lowest priority)
  when (io.ext_w_en) {
    wr_en(io.ext_w_addr)  := true.B
    for (lane <- 0 until K) wr_data(io.ext_w_addr)(lane) := io.ext_w_data(lane)
  }

  // VX writes
  for (p <- 0 until vx_wr) {
    when (io.vx_w_en(p)) {
      wr_en(io.vx_w_addr(p))  := true.B
      for (lane <- 0 until K) wr_data(io.vx_w_addr(p))(lane) := io.vx_w_data(p)(lane)
    }
  }

  // VE writes (split each 2N-bit lane into two N-bit rows)
  for (p <- 0 until ve_wr) {
    when (io.ve_w_en(p)) {
      val base = io.ve_w_addr(p) ## 0.U(1.W)
      val r0 = base
      val r1 = base + 1.U
      wr_en(r0) := true.B
      wr_en(r1) := true.B
      for (lane <- 0 until K) {
        wr_data(r0)(lane) := io.ve_w_data(p)(lane)(N-1, 0)
        wr_data(r1)(lane) := io.ve_w_data(p)(lane)(2*N-1, N)
      }
    }
  }

  // VR writes (split each 4N-bit lane into four N-bit rows) — highest priority
  for (p <- 0 until vr_wr) {
    when (io.vr_w_en(p)) {
      val base = io.vr_w_addr(p) ## 0.U(2.W)
      for (sub <- 0 until 4) {
        val row = base + sub.U
        wr_en(row) := true.B
        for (lane <- 0 until K) {
          wr_data(row)(lane) := io.vr_w_data(p)(lane)(N*(sub+1)-1, N*sub)
        }
      }
    }
  }

  // Clock-edge write
  for (row <- 0 until L) {
    when (wr_en(row)) {
      mem(row) := wr_data(row)
    }
  }
}

// See README.md for license details.
// Tests for MultiWidthRegisterBlock: VX/VE/VR aliasing and write-back.

package sram.mwreg

import scala.util.Random
import chisel3._
import chisel3.simulator.EphemeralSimulator._
import org.scalatest.flatspec.AnyFlatSpec

class MultiWidthRegisterSpec extends AnyFlatSpec {
  val L = 32; val K = 8; val N = 8
  val N2 = 2 * N; val N4 = 4 * N
  val rand = new Random(0xBEEF)

  def randBytes(n: Int): Array[Int] = Array.fill(n)(rand.nextInt(256))

  "MultiWidthRegisterBlock" should "write VX and read back via VX" in {
    simulate(new MultiWidthRegisterBlock(L, K, N)) { dut =>
      // default disable everything
      dut.io.vx_w_en(0).poke(false.B)
      dut.io.vx_w_en(1).poke(false.B)
      dut.io.ve_w_en(0).poke(false.B)
      dut.io.vr_w_en(0).poke(false.B)
      dut.io.vr_w_en(1).poke(false.B)
      dut.io.ext_w_en.poke(false.B)
      for (p <- 0 until 4) dut.io.vx_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.ve_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.vr_r_addr(p).poke(0.U)
      dut.io.ext_r_addr.poke(0.U)

      val data = randBytes(K)
      val addr = 5

      dut.io.vx_w_en(0).poke(true.B)
      dut.io.vx_w_addr(0).poke(addr.U)
      data.zipWithIndex.foreach { case (v, i) => dut.io.vx_w_data(0)(i).poke(v.U) }
      dut.clock.step()

      dut.io.vx_w_en(0).poke(false.B)
      dut.io.vx_r_addr(0).poke(addr.U)
      for (i <- 0 until K) {
        dut.io.vx_r_data(0)(i).expect(data(i).U, s"VX read lane $i mismatch")
      }
    }
  }

  "MultiWidthRegisterBlock" should "write VX and read back as VE (aliasing)" in {
    simulate(new MultiWidthRegisterBlock(L, K, N)) { dut =>
      dut.io.vx_w_en(0).poke(false.B)
      dut.io.vx_w_en(1).poke(false.B)
      dut.io.ve_w_en(0).poke(false.B)
      dut.io.vr_w_en(0).poke(false.B)
      dut.io.vr_w_en(1).poke(false.B)
      dut.io.ext_w_en.poke(false.B)
      for (p <- 0 until 4) dut.io.vx_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.ve_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.vr_r_addr(p).poke(0.U)
      dut.io.ext_r_addr.poke(0.U)

      // VE[2] = VX[4] ∥ VX[5]
      val veIdx = 2
      val vx0Idx = 4; val vx1Idx = 5

      val dataVX0 = randBytes(K)
      val dataVX1 = randBytes(K)

      // Write VX[4]
      dut.io.vx_w_en(0).poke(true.B)
      dut.io.vx_w_addr(0).poke(vx0Idx.U)
      dataVX0.zipWithIndex.foreach { case (v, i) => dut.io.vx_w_data(0)(i).poke(v.U) }
      dut.clock.step()

      // Write VX[5]
      dut.io.vx_w_addr(0).poke(vx1Idx.U)
      dataVX1.zipWithIndex.foreach { case (v, i) => dut.io.vx_w_data(0)(i).poke(v.U) }
      dut.clock.step()
      dut.io.vx_w_en(0).poke(false.B)

      // Read via VE[2]
      dut.io.ve_r_addr(0).poke(veIdx.U)
      for (i <- 0 until K) {
        val loExpected = dataVX0(i)
        val hiExpected = dataVX1(i)
        val veExpected = ((hiExpected & 0xFF) << N) | (loExpected & 0xFF)
        dut.io.ve_r_data(0)(i).expect(veExpected.U,
          s"VE alias lane $i: expected ${veExpected.toHexString} lo=$loExpected hi=$hiExpected")
      }
    }
  }

  "MultiWidthRegisterBlock" should "write VR and read back via VX (aliasing)" in {
    simulate(new MultiWidthRegisterBlock(L, K, N)) { dut =>
      dut.io.vx_w_en(0).poke(false.B)
      dut.io.vx_w_en(1).poke(false.B)
      dut.io.ve_w_en(0).poke(false.B)
      dut.io.vr_w_en(0).poke(false.B)
      dut.io.vr_w_en(1).poke(false.B)
      dut.io.ext_w_en.poke(false.B)
      for (p <- 0 until 4) dut.io.vx_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.ve_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.vr_r_addr(p).poke(0.U)
      dut.io.ext_r_addr.poke(0.U)

      // Write VR[1] (= VX[4..7])
      val vrIdx = 1
      val data32 = Array.fill(K)(rand.nextInt(Int.MaxValue) & 0xFFFFFFFFL).map(_.toInt)

      dut.io.vr_w_en(0).poke(true.B)
      dut.io.vr_w_addr(0).poke(vrIdx.U)
      data32.zipWithIndex.foreach { case (v, i) => dut.io.vr_w_data(0)(i).poke(v.U) }
      dut.clock.step()
      dut.io.vr_w_en(0).poke(false.B)

      // Read back via VR
      dut.io.vr_r_addr(0).poke(vrIdx.U)
      for (i <- 0 until K) {
        dut.io.vr_r_data(0)(i).expect((data32(i) & 0xFFFFFFFFL).U,
          s"VR readback lane $i")
      }

      // Read via constituent VX rows
      for (sub <- 0 until 4) {
        val vxRow = vrIdx * 4 + sub
        dut.io.vx_r_addr(0).poke(vxRow.U)
        for (i <- 0 until K) {
          val byteVal = (data32(i) >> (N * sub)) & 0xFF
          dut.io.vx_r_data(0)(i).expect(byteVal.U,
            s"VR→VX alias row $vxRow lane $i sub=$sub")
        }
      }
    }
  }

  "MultiWidthRegisterBlock" should "external write and read" in {
    simulate(new MultiWidthRegisterBlock(L, K, N)) { dut =>
      dut.io.vx_w_en(0).poke(false.B)
      dut.io.vx_w_en(1).poke(false.B)
      dut.io.ve_w_en(0).poke(false.B)
      dut.io.vr_w_en(0).poke(false.B)
      dut.io.vr_w_en(1).poke(false.B)
      for (p <- 0 until 4) dut.io.vx_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.ve_r_addr(p).poke(0.U)
      for (p <- 0 until 2) dut.io.vr_r_addr(p).poke(0.U)
      dut.io.ext_r_addr.poke(0.U)

      val data = randBytes(K)
      dut.io.ext_w_en.poke(true.B)
      dut.io.ext_w_addr.poke(10.U)
      data.zipWithIndex.foreach { case (v, i) => dut.io.ext_w_data(i).poke(v.U) }
      dut.clock.step()
      dut.io.ext_w_en.poke(false.B)

      dut.io.ext_r_addr.poke(10.U)
      for (i <- 0 until K) {
        dut.io.ext_r_data(i).expect(data(i).U, s"ext read lane $i")
      }
    }
  }
}

  // ---- External VR access (for reading INT32 / FP32 results) ----
  val vr_rd_addr  = Input(UInt(VR_ADDR.W))
  val vr_rd_data  = Output(Vec(K, UInt(N4.W)))
})

// ==========================================================================
// Instruction decoder
// ==========================================================================
val decoder = Module(new InstrDecoder)
decoder.io.instr := io.instr
io.illegal_out   := decoder.io.illegal
val dec = decoder.io.decoded

// ==========================================================================
// Multi-width register file
// ==========================================================================
val rf = Module(new MultiWidthRegisterBlock(L, K, N,
  vx_rd = 4, vx_wr = 2, ve_rd = 2, ve_wr = 1, vr_rd = 2, vr_wr = 2))

// ---- VX reads ----
rf.io.vx_r_addr(0) := io.mma_a_addr    // MMALU A
rf.io.vx_r_addr(1) := io.vx_a_addr     // VALU in_a_vx
rf.io.vx_r_addr(2) := io.vx_b_addr     // VALU in_b_vx
rf.io.vx_r_addr(3) := io.ext_rd_addr   // external
io.ext_rd_data      := rf.io.vx_r_data(3)

// ---- VE reads ----
rf.io.ve_r_addr(0) := io.ve_a_addr
rf.io.ve_r_addr(1) := io.ve_b_addr

// ---- VR reads ----
rf.io.vr_r_addr(0) := io.vr_a_addr
rf.io.vr_r_addr(1) := io.vr_b_addr
io.vr_rd_data       := rf.io.vr_r_data(0)

// Drive the external read port of the RF (separate from vx_r_addr)
rf.io.ext_r_addr := io.ext_rd_addr

// ---- Default: all write ports disabled ----
rf.io.vx_w_en  := VecInit(Seq.fill(2)(false.B))
rf.io.ve_w_en  := VecInit(Seq.fill(1)(false.B))
rf.io.vr_w_en  := VecInit(Seq.fill(2)(false.B))
rf.io.vx_w_addr := VecInit(Seq.fill(2)(0.U(VX_ADDR.W)))
rf.io.ve_w_addr := VecInit(Seq.fill(1)(0.U(VE_ADDR.W)))
rf.io.vr_w_addr := VecInit(Seq.fill(2)(0.U(VR_ADDR.W)))
for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vx_w_data(p)(lane) := 0.U
for (p <- 0 until 1) for (lane <- 0 until K) rf.io.ve_w_data(p)(lane) := 0.U
for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vr_w_data(p)(lane) := 0.U

// ---- External write ----
rf.io.ext_w_en   := io.ext_wr_en
rf.io.ext_w_addr := io.ext_wr_addr
rf.io.ext_w_data := io.ext_wr_data

// ==========================================================================
// MMALU (systolic array; n = K lanes, nbits = N)
// ==========================================================================
val mmalu = Module(new MMALU(new MMPE(N), K, N, N4))
mmalu.io.in_a := VecInit(rf.io.vx_r_data(0).map(_.asSInt))
// MMALU in_b taken from VX (same layout as in_a, different addr)
rf.io.vx_r_addr(0) := io.mma_a_addr  // already assigned above; in_b via separate VX port
// Note: we route MMALU in_b through vx_r_data(0) with mma_b_addr
// To give MMALU its own B port, we repurpose ext port when no ext read is active.
// For simplicity in tests, use the same vx_r_data(3) for MMALU B (driven by mma_b_addr).
rf.io.vx_r_addr(3) := Mux(io.ext_wr_en || io.ext_rd_addr.orR, io.ext_rd_addr, io.mma_b_addr)
mmalu.io.in_b     := VecInit(rf.io.vx_r_data(3).map(_.asSInt))
mmalu.io.in_accum := VecInit(Seq.fill(K)(0.S(N4.W)))

// MMALU control from decoded instruction
mmalu.io.ctrl.keep      := dec.mma_keep
mmalu.io.ctrl.use_accum := false.B
mmalu.io.ctrl.busy      := (dec.family === OpFamily.MMA)

// MMALU write-back directly to VR (port 1) — NO precision truncation
// mmalu.io.out is Vec(K, SInt(N4.W)) = Vec(K, SInt(32.W)) for N=8
when (dec.family === OpFamily.MMA) {
  rf.io.vr_w_en(1)   := true.B
  rf.io.vr_w_addr(1) := io.mma_out_addr
  for (lane <- 0 until K) {
    rf.io.vr_w_data(1)(lane) := mmalu.io.out(lane).asUInt
  }
}

// ==========================================================================
// VALU
// ==========================================================================
val valu = Module(new VALU(K, N))

// Connect inputs from RF
for (lane <- 0 until K) {
  valu.io.in_a_vx(lane) := rf.io.vx_r_data(1)(lane)
  valu.io.in_b_vx(lane) := rf.io.vx_r_data(2)(lane)
  valu.io.in_a_ve(lane) := rf.io.ve_r_data(0)(lane)
  valu.io.in_b_ve(lane) := rf.io.ve_r_data(1)(lane)
  valu.io.in_a_vr(lane) := rf.io.vr_r_data(0)(lane)
  valu.io.in_b_vr(lane) := rf.io.vr_r_data(1)(lane)
  valu.io.in_c_vr(lane) := rf.io.vr_r_data(1)(lane)  // C re-uses B port for now
}

// Drive VALU ctrl from decoded bundle
valu.io.ctrl := dec.valu

// Determine if this is a VALU family
val isVALU = dec.family === OpFamily.VALU_ARITH  ||
             dec.family === OpFamily.VALU_LOGIC   ||
             dec.family === OpFamily.VALU_REDUCE  ||
             dec.family === OpFamily.VALU_LUT     ||
             dec.family === OpFamily.VALU_CVT     ||
             dec.family === OpFamily.VALU_BCAST   ||
             dec.family === OpFamily.VALU_FP      ||
             dec.family === OpFamily.VALU_FP_FMA  ||
             dec.family === OpFamily.VALU_MOV

// VALU write-back (port 0 for each class)
when (isVALU) {
  // VX write-back.
  // isReduceToVR ops (vsum, vrmax, vrmin) encode their *input* class in regCls
  // (e.g. vsum.vx has regCls=VX so the VALU selects the VX reduction path).
  // That would accidentally assert vx_w_en and clobber vx_out_addr — suppress it.
  // isSetLut ops (vsetlut) write only to VALU-internal bank registers;
  // all RF write ports must be suppressed.
  rf.io.vx_w_en(0)   := ((dec.valu.regCls === W.VX) || isNarrowCvtOut(dec.valu.op)) &&
                         !isReduceToVR(dec.valu.op) &&
                         !isSetLut(dec.valu.op)
  rf.io.vx_w_addr(0) := io.vx_out_addr
  for (lane <- 0 until K) rf.io.vx_w_data(0)(lane) := valu.io.out_vx(lane)

  // VE write-back
  rf.io.ve_w_en(0)   := dec.valu.regCls === W.VE
  rf.io.ve_w_addr(0) := io.ve_out_addr
  for (lane <- 0 until K) rf.io.ve_w_data(0)(lane) := valu.io.out_ve(lane)

  // VR write-back (FP/INT32, wide conversion results, and horizontal reductions).
  // vsetlut has regCls=VR but must NOT write the RF — suppress it.
  rf.io.vr_w_en(0)   := ((dec.valu.regCls === W.VR) || isWideCvtOut(dec.valu.op) ||
                          isReduceToVR(dec.valu.op)) &&
                         !isSetLut(dec.valu.op)
  rf.io.vr_w_addr(0) := io.vr_out_addr
  for (lane <- 0 until K) rf.io.vr_w_data(0)(lane) := valu.io.out_vr(lane)
}

// ==========================================================================
// Helpers: determine output register class for conversion and reduce ops
// ==========================================================================
def isNarrowCvtOut(op: VecOp.Type): Bool = {
  op === VecOp.vcvt_s8_s32 ||  // s8 sign-extend → VX slice
  op === VecOp.vcvt_f32_s8     // FP32 → INT8 narrow
  // vcvt_s8_f32 = INT8→FP32: wide output → VR, NOT narrow
}

def isWideCvtOut(op: VecOp.Type): Bool = {
  op === VecOp.vcvt_s32_f32  ||  // s32→f32: wide
  op === VecOp.vcvt_s8_f32   ||  // s8→f32: wide
  op === VecOp.vcvt_f32_s32  ||
  op === VecOp.vcvt_s32_s8   ||
  op === VecOp.vcvt_f32_bf8  ||
  op === VecOp.vcvt_bf8_f32  ||
  op === VecOp.vcvt_f32_bf16 ||
  op === VecOp.vcvt_bf16_f32 ||
  op === VecOp.vcvt_s16_s32  ||
  op === VecOp.vcvt_s32_s16
}

/**
 * vsetlut writes only to VALU-internal LUT bank registers.
 * All register-file write ports must be suppressed for this op.
 */
def isSetLut(op: VecOp.Type): Bool = op === VecOp.vsetlut

