class RegisterCell(val n: Int = 8, val nbits: Int = 8) extends Module {
    val io = IO(
        new Bundle {
            val d_in    = Input(Vec(n, SInt(nbits.W)))
            val d_out   = Output(Vec(n, SInt(nbits.W)))
            val en_wr   = Input(Bool())
        }
    )

    val reg = RegInit(VecInit(Seq.fill(n)(0.S(nbits.W))))
    io.d_out := reg

    when (io.en_wr) {
        reg := io.d_in
    }
}

